474	 * Write or merge the Codex config.toml.
475	 *
476	 * Reads the generated config.toml from the nx-ai-agents-config repo (which
477	 * contains MCP servers, agent definitions, and feature flags) and deep-merges
478	 * it into the user's existing config.toml using proper TOML parsing.
479	 *
480	 * Merge rules:
481	 * - [mcp_servers."nx-mcp"] — upsert with version-adjusted args, preserving extra user args
482	 * - [features] multi_agent — set to true unless user has explicitly set it to false
483	 * - [agents.*] — upsert each agent definition
484	 * - All other user config is preserved untouched
485	 *
486	 * Falls back to a minimal hardcoded MCP config if the generated file is unavailable.
487	 */
488	function writeCodexConfig(
489	  tree: Tree,
490	  codexTomlPath: string,
491	  nxVersion: string,
492	  aiConfigRepoPath?: string
493	): void {
494	  let generated: Record<string, any> | null = null;
495	
496	  if (aiConfigRepoPath) {
497	    const generatedConfigPath = join(
498	      aiConfigRepoPath,
499	      'generated',
500	      '.codex',
501	      'config.toml'
502	    );
503	    if (existsSync(generatedConfigPath)) {
504	      const generatedConfig = readFileSync(generatedConfigPath, 'utf-8');
505	      generated = TOML.parse(generatedConfig) as Record<string, any>;
506	    }
507	  }
508	
509	  if (!generated) {
510	    // Fallback: use hardcoded MCP-only config (no agents/features)
511	    const tomlConfig = getNxMcpTomlConfig(nxVersion);
512	    if (!tree.exists(codexTomlPath)) {
513	      tree.write(codexTomlPath, tomlConfig);
514	    } else {
515	      const existing = tree.read(codexTomlPath, 'utf-8');
516	      if (!existing.includes(nxMcpTomlHeader)) {
517	        tree.write(codexTomlPath, existing + '\n' + tomlConfig);
518	      }
519	    }
520	    return;
521	  }
522	
523	  // Parse existing config (or start empty)
524	  let config: Record<string, any> = {};
525	  if (tree.exists(codexTomlPath)) {
526	    try {
527	      config = TOML.parse(tree.read(codexTomlPath, 'utf-8')) as Record<
528	        string,
529	        any
530	      >;
